			}
			// Also if ident is not basic, maybe need DeepEqual? For fmt.Stringer etc, original used DeepEqual for fmt.Stringer return (it was struct? Actually fmt.Stringer is interface, but it used DeepEqual)
			// For interface types from other packages, need DeepEqual? In earlier example with fmt.Stringer, it used DeepEqual.
			// So for any type that is not basic and not pointer to basic, use DeepEqual?
			// Let's list basic types that can use ==
			basics := map[string]bool{
