func typeToString(expr ast.Expr, tpMap map[string]string) string {
	if expr == nil {
		return ""
	}
	// Clone and replace
	cloned := cloneAndReplace(expr, tpMap)
	var buf bytes.Buffer
	fset := token.NewFileSet()
	printer.Fprint(&buf, fset, cloned)
	s := buf.String()
	// For ellipsis, it prints "..."
	// For variadic handling we already handled
	return s
}

func cloneAndReplace(expr ast.Expr, tpMap map[string]string) ast.Expr {
	if expr == nil {
		return nil
	}
	switch e := expr.(type) {
	case *ast.Ident:
		if concrete, ok := tpMap[e.Name]; ok {
			// concrete may be like "int" or "string" or more complex? For now assume simple ident
			return &ast.Ident{Name: concrete}
		}
		return &ast.Ident{Name: e.Name}
	case *ast.StarExpr:
		return &ast.StarExpr{X: cloneAndReplace(e.X, tpMap)}
	case *ast.ArrayType:
		return &ast.ArrayType{
			Len: e.Len,
			Elt: cloneAndReplace(e.Elt, tpMap),
		}
	case *ast.MapType:
		return &ast.MapType{
			Key: cloneAndReplace(e.Key, tpMap),
			Value: cloneAndReplace(e.Value, tpMap),
		}
	case *ast.ChanType:
		return &ast.ChanType{
			Dir: e.Dir,
			Value: cloneAndReplace(e.Value, tpMap),
		}
	case *ast.FuncType:
		// params and results
		var params *ast.FieldList
		if e.Params != nil {
			params = &ast.FieldList{}
			for _, field := range e.Params.List {
				newField := &ast.Field{
					Type: cloneAndReplace(field.Type, tpMap),
				}
				if field.Names != nil {
					newField.Names = field.Names
				}
				params.List = append(params.List, newField)
			}
		}
		var results *ast.FieldList
		if e.Results != nil {
			results = &ast.FieldList{}
			for _, field := range e.Results.List {
				newField := &ast.Field{
					Type: cloneAndReplace(field.Type, tpMap),
				}
				if field.Names != nil {
					newField.Names = field.Names
				}
				results.List = append(results.List, newField)
			}
		}
		// handle type params?
		return &ast.FuncType{
			Params: params,
			Results: results,
		}
	case *ast.Ellipsis:
		return &ast.Ellipsis{Elt: cloneAndReplace(e.Elt, tpMap)}
	case *ast.SelectorExpr:
		// pkg.Type, don't replace
		return &ast.SelectorExpr{
			X: cloneAndReplace(e.X, tpMap),
			Sel: &ast.Ident{Name: e.Sel.Name},
		}
	case *ast.IndexExpr:
		return &ast.IndexExpr{
			X: cloneAndReplace(e.X, tpMap),
			Index: cloneAndReplace(e.Index, tpMap),
		}
	case *ast.IndexListExpr:
		var indices []ast.Expr
		for _, idx := range e.Indices {
			indices = append(indices, cloneAndReplace(idx, tpMap))
		}
		return &ast.IndexListExpr{
			X: cloneAndReplace(e.X, tpMap),
			Indices: indices,
		}
	case *ast.InterfaceType:
		return e // for simplicity, keep as is? But need to replace inside?
		// We'll not deep clone interface
	case *ast.StructType:
		return e
	default:
		// fallback: use original
		return expr
	}
	return expr
}

