func generateErrorMessageForWant(fn FuncInfo, idx int, indent string, iFlag bool, namedFlag bool, useGoCmpFlag bool) string {
	var buf bytes.Buffer
	// Determine prefix
	var prefix string
	if fn.Receiver != nil {
		prefix = fn.Receiver.TypeName + "." + fn.Name
	} else {
		prefix = fn.Name
	}
	gotName := "got"
	if idx > 0 {
		gotName = fmt.Sprintf("got%d", idx)
	}
	wantName := "want"
	if idx > 0 {
		wantName = fmt.Sprintf("want%d", idx)
	}
	// For multi returns, message is like "Func() got = %v, want %v" or "Func() got1 = %v, want %v"
	// For single return, "Func() = %v, want %v"
	nonErr := len(fn.Results)
	if fn.HasError {
		nonErr--
	}
	var format string
	var args []string

	if nonErr > 1 {
		// multi
		format = fmt.Sprintf("%s() %s = %%v, %s %%v", prefix, gotName, wantName)
		args = []string{gotName, "tt." + wantName}
	} else {
		// single
		format = fmt.Sprintf("%s() = %%v, %s %%v", prefix, wantName)
		args = []string{gotName, "tt." + wantName}
	}

	if iFlag && len(fn.Params) > 0 {
		// Include inputs: format like "Foo(%v, %v) = %v, want %v"
		// Need to insert args placeholders before got/want
		inputFormat := prefix + "("
		var inputPlaceholders []string
		var inputArgs []string
		for idx, p := range fn.Params {
			if idx > 0 {
				inputFormat += ", "
			}
			inputFormat += "%v"
			argName := p.Name
			if argName == "" || argName == "_" {
				argName = fmt.Sprintf("in%d", idx)
			}
			inputArgs = append(inputArgs, fmt.Sprintf("tt.args.%s", argName))
		}
		inputFormat += ")"
		// Now combine: inputFormat + " = %v, want %v" etc.
		if nonErr > 1 {
			format = fmt.Sprintf("%s %s = %%v, %s %%v", inputFormat, gotName, wantName)
		} else {
			format = fmt.Sprintf("%s = %%v, %s %%v", inputFormat, wantName)
		}
		args = append(inputArgs, args...)
	}

	if useGoCmpFlag {
		// For cmp, format includes diff
		// t.Errorf("Foo() = %v, want %v\ndiff=%s", got, tt.want, cmp.Diff(tt.want, got))
		format = format + "\ndiff=%s"
		// args for diff: need tt.want, got for cmp.Diff order? Original had cmp.Diff(tt.want, got) and message got, tt.want, diff
		// For deep equal case with cmp, original had: t.Errorf("GenericFunc() = %v, want %v\ndiff=%s", got, tt.want, cmp.Diff(tt.want, got))
		// Note order: got first, want second in message, but Diff is want, got
		// For want checks with cmp, we should generate: t.Errorf("<format>\ndiff=%s", <args>, cmp.Diff(tt.want, got))
		// Where <args> are got, tt.want (or with inputs)
		// Let's add diff arg
		diffArgs := fmt.Sprintf("cmp.Diff(tt.%s, %s)", wantName, gotName)
		allArgs := append(args, diffArgs)
		buf.WriteString(fmt.Sprintf("%st.Errorf(\"%s\", %s)\n", indent+"\t", format, strings.Join(allArgs, ", ")))
	} else {
		// check if needs DeepEqual: if so, message same as == case? Original used same message for both == and DeepEqual, just condition differs
		buf.WriteString(fmt.Sprintf("%st.Errorf(\"%s\", %s)\n", indent+"\t", format, strings.Join(args, ", ")))
	}
	return buf.String()
}

