func generateErrorMessage(fn FuncInfo, indent string, isErrorCheck bool, iFlag bool, namedFlag bool) string {
	var buf bytes.Buffer
	// isErrorCheck true means this is for error check (wantErr)
	// Generate format string for t.Errorf or t.Fatalf

