	// Determine function prefix
	var prefix string
	if fn.Receiver != nil {
		prefix = fn.Receiver.TypeName + "." + fn.Name
	} else {
		prefix = fn.Name
	}

	if isErrorCheck {
		// Error check uses Fatalf for functions with returns, Errorf for only error?
		// Original: For function with only error return, it used Errorf, not Fatalf. For function with return + error, it used Fatalf for error check.
		// Let's determine: If fn has non-error returns (i.e., len(results)>1 or results>0 and hasError), then error check uses Fatalf, else Errorf.
		hasReturns := len(fn.Results) > 1 || (len(fn.Results) == 1 && !fn.HasError) || (len(fn.Results) > 1 && fn.HasError)
