		nonErr := len(fn.Results)
		if fn.HasError {
			nonErr--
		}
		useFatal := nonErr > 0
		verb := "Errorf"
		if useFatal {
			verb = "Fatalf"
		}

		if iFlag && len(fn.Params) > 0 {
			// Include args in message
			format := prefix + "("
			var placeholders []string
			var argValues []string
			for idx, p := range fn.Params {
				if idx > 0 {
					format += ", "
				}
				format += "%v"
				argName := p.Name
				if argName == "" || argName == "_" {
					argName = fmt.Sprintf("in%d", idx)
				}
				argValues = append(argValues, fmt.Sprintf("tt.args.%s", argName))
			}
			format += ") error = %%v, wantErr %%v"
			allArgs := append(argValues, "err", "tt.wantErr")
			buf.WriteString(fmt.Sprintf("%st.%s(\"%s\", %s)\n", indent+"\t", verb, format, strings.Join(allArgs, ", ")))
		} else {
			// No inputs
			buf.WriteString(fmt.Sprintf("%st.%s(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", indent+"\t", verb, prefix))
		}
	} else {
