	flag.BoolVar(&parallelFlag, "parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
	flag.StringVar(&templateFlag, "template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
	flag.StringVar(&templateDirFlag, "template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
	flag.StringVar(&templateParamsFlag, "template_params", "", "read external parameters to template by json with stdin")
	flag.StringVar(&templateParamsFileFlag, "template_params_file", "", "read external parameters to template by json with file")
	flag.BoolVar(&useGoCmpFlag, "use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
	flag.BoolVar(&versionFlag, "version", false, "print version information and exit")
	flag.BoolVar(&wFlag, "w", false, "write output to (test) files instead of stdout")
}

