	flag.IntVar(&aiMinCasesFlag, "ai-min-cases", 3, "minimum number of test cases to generate with AI (default 3)")
	flag.StringVar(&aiModelFlag, "ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation (default \"qwen2.5-coder:0.5b\")")
	flag.BoolVar(&allFlag, "all", false, "generate tests for all functions and methods")
	flag.StringVar(&exclFlag, "excl", "", "regexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all")
	flag.BoolVar(&exportedFlag, "exported", false, "generate tests for exported functions and methods. Takes precedence over -only and -all")
	flag.BoolVar(&iFlag, "i", false, "print test inputs in error messages")
	flag.BoolVar(&namedFlag, "named", false, "switch table tests from using slice to map (with test name for the key)")
	flag.BoolVar(&nosubtestsFlag, "nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
	flag.StringVar(&onlyFlag, "only", "", "regexp. generate tests for functions and methods that match only. Takes precedence over -all")
	flag.BoolVar(&parallelFlag, "parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
	flag.StringVar(&templateFlag, "template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
	flag.StringVar(&templateDirFlag, "template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
	flag.StringVar(&templateParamsFlag, "template_params", "", "read external parameters to template by json with stdin")
	flag.StringVar(&templateParamsFileFlag, "template_params_file", "", "read external parameters to template by json with file")
	flag.BoolVar(&useGoCmpFlag, "use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
	flag.BoolVar(&versionFlag, "version", false, "print version information and exit")
	flag.BoolVar(&wFlag, "w", false, "write output to (test) files instead of stdout")
}

