						} else {
							buf.WriteString(fmt.Sprintf("%stt.assertion(t, %s, fmt.Sprintf(\"%s\"))\n", innerIndent, call, fmtStr))
						}
					} else {
						buf.WriteString(fmt.Sprintf("%stt.assertion(t, %s, fmt.Sprintf(\"%s\", %s))\n", innerIndent, call, fmtStr, strings.Join(fmtArgs, ", ")))
					}
				} else {
					buf.WriteString(fmt.Sprintf("%stt.assertion(t, %s)\n", innerIndent, call))
				}
			}
		} else {
			buf.WriteString(fmt.Sprintf("%stt.assertion(t, %s)\n", innerIndent, call))
		}
	} else {
		if nonErr == 1 && !fn.HasError {
			if iFlag || nosubtestsFlag {
				fmtStr, fmtArgs := buildFormat()
				if len(fmtArgs) > 0 {
					buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.want, %s, \"%s\", %s)\n", innerIndent, call, fmtStr, strings.Join(fmtArgs, ", ")))
				} else {
					buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.want, %s, \"%s\")\n", innerIndent, call, fmtStr))
				}
			} else {
				buf.WriteString(fmt.Sprintf("%sassert.Equal(t, tt.want, %s)\n", innerIndent, call))
			}
		} else {
			var gotVars []string
			for i := 0; i < nonErr; i++ {
				if i == 0 {
					gotVars = append(gotVars, "got")
				} else {
					gotVars = append(gotVars, fmt.Sprintf("got%d", i))
				}
			}
			if fn.HasError {
				gotVars = append(gotVars, "err")
			}
			gotStr := strings.Join(gotVars, ", ")
			buf.WriteString(fmt.Sprintf("%s%s := %s\n", innerIndent, gotStr, call))
			if fn.HasError {
				if iFlag || nosubtestsFlag {
					fmtStr, fmtArgs := buildFormat()
					if len(fmtArgs) > 0 {
						buf.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\"%s\", %s))\n", innerIndent, fmtStr, strings.Join(fmtArgs, ", ")))
					} else {
						buf.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\"%s\"))\n", innerIndent, fmtStr))
					}
				} else {
					buf.WriteString(fmt.Sprintf("%stt.assertion(t, err)\n", innerIndent))
				}
			}
			for i := 0; i < nonErr; i++ {
				wantName := "want"
				if i > 0 {
					wantName = fmt.Sprintf("want%d", i)
				}
				gotName := "got"
				if i > 0 {
					gotName = fmt.Sprintf("got%d", i)
				}
				if iFlag || nosubtestsFlag {
					fmtStr, fmtArgs := buildFormat()
					if len(fmtArgs) > 0 {
						buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%s\", %s)\n", innerIndent, wantName, gotName, fmtStr, strings.Join(fmtArgs, ", ")))
					} else {
						buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%s\")\n", innerIndent, wantName, gotName, fmtStr))
					}
				} else {
					buf.WriteString(fmt.Sprintf("%sassert.Equal(t, tt.%s, %s)\n", innerIndent, wantName, gotName))
				}
			}
		}
	}

	if !nosubtestsFlag {
		buf.WriteString("\t\t})\n")
		buf.WriteString("\t}\n")
	} else {
		buf.WriteString("\t}\n")
	}
	buf.WriteString("}\n")
	return buf.String()
}
