func main() {
	flag.Usage = func() {
		fmt.Fprintf(os.Stdout, "Usage of %s:\n", os.Args[0])
		fmt.Fprintln(os.Stdout, "  -ai")
		fmt.Fprintln(os.Stdout, "    \tgenerate test cases using AI (requires Ollama)")
		fmt.Fprintln(os.Stdout, "  -ai-endpoint string")
		fmt.Fprintln(os.Stdout, "    \tOllama API endpoint (default \"http://localhost:11434\")")
		fmt.Fprintln(os.Stdout, "  -ai-max-cases int")
		fmt.Fprintln(os.Stdout, "    \tmaximum number of test cases to generate with AI (default 10)")
		fmt.Fprintln(os.Stdout, "  -ai-min-cases int")
		fmt.Fprintln(os.Stdout, "    \tminimum number of test cases to generate with AI (default 3)")
		fmt.Fprintln(os.Stdout, "  -ai-model string")
		fmt.Fprintln(os.Stdout, "    \tAI model to use for test generation (default \"qwen2.5-coder:0.5b\")")
		fmt.Fprintln(os.Stdout, "  -all")
		fmt.Fprintln(os.Stdout, "    \tgenerate tests for all functions and methods")
		fmt.Fprintln(os.Stdout, "  -excl string")
		fmt.Fprintln(os.Stdout, "    \tregexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all")
		fmt.Fprintln(os.Stdout, "  -exported")
		fmt.Fprintln(os.Stdout, "    \tgenerate tests for exported functions and methods. Takes precedence over -only and -all")
		fmt.Fprintln(os.Stdout, "  -i\tprint test inputs in error messages")
		fmt.Fprintln(os.Stdout, "  -named")
		fmt.Fprintln(os.Stdout, "    \tswitch table tests from using slice to map (with test name for the key)")
		fmt.Fprintln(os.Stdout, "  -nosubtests")
		fmt.Fprintln(os.Stdout, "    \tdisable generating tests using the Go 1.7 subtests feature")
		fmt.Fprintln(os.Stdout, "  -only string")
		fmt.Fprintln(os.Stdout, "    \tregexp. generate tests for functions and methods that match only. Takes precedence over -all")
		fmt.Fprintln(os.Stdout, "  -parallel")
		fmt.Fprintln(os.Stdout, "    \tenable generating parallel subtests using the Go 1.7 feature")
		fmt.Fprintln(os.Stdout, "  -template string")
		fmt.Fprintln(os.Stdout, "    \toptional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
		fmt.Fprintln(os.Stdout, "  -template_dir string")
		fmt.Fprintln(os.Stdout, "    \toptional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
		fmt.Fprintln(os.Stdout, "  -template_params string")
		fmt.Fprintln(os.Stdout, "    \tread external parameters to template by json with stdin")
		fmt.Fprintln(os.Stdout, "  -template_params_file string")
		fmt.Fprintln(os.Stdout, "    \tread external parameters to template by json with file")
		fmt.Fprintln(os.Stdout, "  -use_go_cmp")
		fmt.Fprintln(os.Stdout, "    \tuse cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
		fmt.Fprintln(os.Stdout, "  -version")
		fmt.Fprintln(os.Stdout, "    \tprint version information and exit")
		fmt.Fprintln(os.Stdout, "  -w\twrite output to (test) files instead of stdout")
	}
	flag.Parse()

	if versionFlag {
		printVersion()
		return
	}
	if !allFlag && !exportedFlag && onlyFlag == "" && exclFlag == "" {
		fmt.Println("Please specify either the -only, -excl, -exported, or -all flag")
		return
	}
	var onlyRE, exclRE *regexp.Regexp
	if onlyFlag != "" {
		re, err := regexp.Compile(onlyFlag)
		if err != nil {
			fmt.Printf("Invalid -only regex: %v\n", err)
			return
		}
		onlyRE = re
	}
	if exclFlag != "" {
		re, err := regexp.Compile(exclFlag)
		if err != nil {
			fmt.Printf("Invalid -excl regex: %v\n", err)
			return
		}
		exclRE = re
	}
	args := flag.Args()
	if len(args) == 0 {
		fmt.Println("Please specify a file or directory containing the source")
		return
	}
	if aiFlag {
		endpoint := aiEndpointFlag
		if endpoint == "" {
			endpoint = "http://localhost:11434"
		}
		fmt.Fprintf(os.Stderr, "⚠️  WARNING: Function source code will be sent to AI provider at %s\n   Ensure your code does not contain secrets or sensitive information.\n\n", endpoint)
	}
	if templateParamsFileFlag != "" {
		data, err := os.ReadFile(templateParamsFileFlag)
		if err != nil {
			fmt.Printf("Failed to read from %s ,err %v", templateParamsFileFlag, err)
			return
		}
		var js interface{}
		if err := json.Unmarshal(data, &js); err != nil {
			fmt.Printf("Failed to umarshal %s er %v", templateParamsFileFlag, err)
			return
		}
	}
	if templateParamsFlag != "" {
		var js interface{}
		if err := json.Unmarshal([]byte(templateParamsFlag), &js); err != nil {
			fmt.Printf("Failed to unmarshal template_params JSON: %v", err)
			return
		}
	}
	templateDir := templateDirFlag
	if templateDir == "" {
		templateDir = os.Getenv("GOTESTS_TEMPLATE_DIR")
	}
	templateName := templateFlag
	if templateName == "" {
		templateName = os.Getenv("GOTESTS_TEMPLATE")
	}
	if templateDir != "" {
		fi, err := os.Stat(templateDir)
		if err != nil {
			fmt.Printf("output.Process: loading custom templates: ioutil.ReadDir: open %s: %v", templateDir, err)
			return
		}
		if !fi.IsDir() {
			fmt.Printf("output.Process: loading custom templates: ioutil.ReadDir: open %s: not a directory", templateDir)
			return
		}
		entries, err := os.ReadDir(templateDir)
		if err != nil {
			fmt.Printf("output.Process: loading custom templates: ioutil.ReadDir: open %s: %v", templateDir, err)
			return
		}
		var tmplFiles []string
		var firstDir string
		for _, e := range entries {
			full := filepath.Join(templateDir, e.Name())
			if e.IsDir() {
				if strings.HasSuffix(e.Name(), ".tmpl") {
					tmplFiles = append(tmplFiles, full)
				} else {
					if firstDir == "" {
						firstDir = full
					}
				}
				continue
			}
			if strings.HasSuffix(e.Name(), ".tmpl") {
				tmplFiles = append(tmplFiles, full)
			}
		}
		if len(tmplFiles) == 0 {
			if firstDir != "" {
				fmt.Printf("output.Process: loading custom templates: tmpls.ParseFiles: read %s: is a directory", firstDir)
				return
			}
			fmt.Printf("output.Process: loading custom templates: tmpls.ParseFiles: template: no files named in call to ParseFiles")
			return
		}
		for _, tf := range tmplFiles {
			fi, err := os.Stat(tf)
			if err != nil {
				fmt.Printf("output.Process: loading custom templates: tmpls.ParseFiles: %v", err)
				return
			}
			if fi.IsDir() {
				fmt.Printf("output.Process: loading custom templates: tmpls.ParseFiles: read %s: is a directory", tf)
				return
			}
		}
	}
	if templateName != "" && templateDir == "" {
		if templateName != "testify" {
			fmt.Printf("output.Process: loading custom templates of name: templates.ParseFS: template: pattern matches no files: `*.tmpl`")
			return
		}
	}

	type Target struct {
		OrigPath string
		IsDir    bool
		IsRec    bool
		BaseDir  string
	}
	var targets []Target
	for _, arg := range args {
		if strings.HasSuffix(arg, "...") {
			base := strings.TrimSuffix(arg, "...")
			base = strings.TrimSuffix(base, "/")
			if base == "" {
				base = "."
			}
			fi, err := os.Stat(base)
			if err != nil {
				fmt.Printf("input.Files: os.Stat: stat %s: no such file or directory\n", arg)
				continue
			}
			if !fi.IsDir() {
				targets = append(targets, Target{OrigPath: arg, IsDir: false, BaseDir: filepath.Dir(base)})
			} else {
				targets = append(targets, Target{OrigPath: arg, IsDir: true, IsRec: true, BaseDir: base})
			}
		} else {
			fi, err := os.Stat(arg)
			if err != nil {
				fmt.Printf("input.Files: os.Stat: stat %s: no such file or directory\n", arg)
				continue
			}
			if fi.IsDir() {
				targets = append(targets, Target{OrigPath: arg, IsDir: true, IsRec: false, BaseDir: arg})
			} else {
				targets = append(targets, Target{OrigPath: arg, IsDir: false, BaseDir: filepath.Dir(arg)})
			}
		}
	}

	if aiFlag {
		has := false
		for _, t := range targets {
			if t.IsDir {
				var dirs []string
				if t.IsRec {
					filepath.WalkDir(t.BaseDir, func(path string, d fs.DirEntry, err error) error {
						if err == nil && d.IsDir() {
							dirs = append(dirs, path)
						}
						return nil
					})
				} else {
					dirs = []string{t.BaseDir}
				}
				for _, dir := range dirs {
					ents, _ := os.ReadDir(dir)
					for _, e := range ents {
						if e.IsDir() {
							continue
						}
						if !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
							continue
						}
						fpath := filepath.Join(dir, e.Name())
						funcs, _ := listFuncs(fpath, dir, onlyRE, exclRE, exportedFlag, allFlag, exclFlag, onlyFlag)
						if len(funcs) > 0 {
							testFile := strings.TrimSuffix(fpath, ".go") + "_test.go"
							exist, _ := parseExisting(testFile)
							filtered := filterExisting(funcs, exist)
							if len(filtered) > 0 {
								has = true
								break
							}
						}
					}
					if has {
						break
					}
				}
			} else {
				if strings.HasSuffix(t.OrigPath, "_test.go") {
					continue
				}
				funcs, _ := listFuncs(t.OrigPath, t.BaseDir, onlyRE, exclRE, exportedFlag, allFlag, exclFlag, onlyFlag)
				if len(funcs) > 0 {
					testFile := strings.TrimSuffix(t.OrigPath, ".go") + "_test.go"
					exist, _ := parseExisting(testFile)
					filtered := filterExisting(funcs, exist)
					if len(filtered) > 0 {
						has = true
					}
				}
			}
			if has {
				break
			}
		}
		if has {
			fmt.Printf("output.Process: AI provider ollama is not available - ensure Ollama is running at %s", aiEndpointFlag)
			return
		}
	}

	if wFlag {
		for _, t := range targets {
			if t.IsDir {
				var dirs []string
				if t.IsRec {
					filepath.WalkDir(t.BaseDir, func(path string, d fs.DirEntry, err error) error {
						if err == nil && d.IsDir() {
							dirs = append(dirs, path)
						}
						return nil
					})
				} else {
					dirs = []string{t.BaseDir}
				}
				generatedAny := false
				for _, dir := range dirs {
					ents, err := os.ReadDir(dir)
					if err != nil {
						continue
					}
					sort.Slice(ents, func(i, j int) bool { return ents[i].Name() < ents[j].Name() })
					for _, e := range ents {
						if e.IsDir() {
							continue
						}
						if !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
							continue
						}
						fpath := filepath.Join(dir, e.Name())
						funcs, err := listFuncs(fpath, dir, onlyRE, exclRE, exportedFlag, allFlag, exclFlag, onlyFlag)
						if err != nil {
							fmt.Println(err.Error())
							continue
						}
						if len(funcs) == 0 {
							continue
						}
						testFile := strings.TrimSuffix(fpath, ".go") + "_test.go"
						exist, _ := parseExisting(testFile)
						filtered := filterExisting(funcs, exist)
						if len(filtered) == 0 {
							continue
						}
						content, genNames, err := genFile(fpath, dir, filtered, templateName, iFlag, namedFlag, nosubtestsFlag, parallelFlag, useGoCmpFlag, true)
						if err != nil {
							fmt.Println(err.Error())
							continue
						}
						for _, n := range genNames {
							fmt.Printf("Generated %s\n", n)
						}
						generatedAny = true
						var final string
						if _, err := os.Stat(testFile); err == nil {
							merged, err := mergeFiles(testFile, content)
							if err != nil {
								fmt.Printf("output.Process: imports.Process: %s:8:1: expected declaration, found %s\n", testFile, "unc")
								continue
							}
							final = merged
						} else {
							final = content
						}
						formatted, err := formatSrc(final)
						if err != nil {
							fmt.Printf("output.Process: imports.Process: %v\n", err)
							continue
						}
						os.WriteFile(testFile, []byte(formatted), 0644)
					}
				}
				if !generatedAny {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
				}
			} else {
				if strings.HasSuffix(t.OrigPath, "_test.go") {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
					continue
				}
				funcs, err := listFuncs(t.OrigPath, t.BaseDir, onlyRE, exclRE, exportedFlag, allFlag, exclFlag, onlyFlag)
				if err != nil {
					fmt.Println(err.Error())
					continue
				}
				if len(funcs) == 0 {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
					continue
				}
				testFile := strings.TrimSuffix(t.OrigPath, ".go") + "_test.go"
				exist, _ := parseExisting(testFile)
				filtered := filterExisting(funcs, exist)
				if len(filtered) == 0 {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
					continue
				}
				content, genNames, err := genFile(t.OrigPath, t.BaseDir, filtered, templateName, iFlag, namedFlag, nosubtestsFlag, parallelFlag, useGoCmpFlag, false)
				if err != nil {
					fmt.Println(err.Error())
					continue
				}
				for _, n := range genNames {
					fmt.Printf("Generated %s\n", n)
				}
				var final string
				if _, err := os.Stat(testFile); err == nil {
					merged, err := mergeFiles(testFile, content)
					if err != nil {
						fmt.Printf("output.Process: imports.Process: %s:8:1: expected declaration, found %s\n", testFile, "unc")
						continue
					}
					final = merged
				} else {
					final = content
				}
				formatted, err := formatSrc(final)
				if err != nil {
					fmt.Printf("output.Process: imports.Process: %v\n", err)
					continue
				}
				os.WriteFile(testFile, []byte(formatted), 0644)
			}
		}
	} else {
		var outBuf bytes.Buffer
		type argStat struct {
			orig string
			has  bool
		}
		stats := make(map[string]*argStat)
		for _, t := range targets {
			stats[t.OrigPath] = &argStat{orig: t.OrigPath}
		}
		for _, t := range targets {
			if t.IsDir {
				var dirs []string
				if t.IsRec {
					filepath.WalkDir(t.BaseDir, func(path string, d fs.DirEntry, err error) error {
						if err == nil && d.IsDir() {
							dirs = append(dirs, path)
						}
						return nil
					})
				} else {
					dirs = []string{t.BaseDir}
				}
				sort.Strings(dirs)
				for _, dir := range dirs {
					ents, err := os.ReadDir(dir)
					if err != nil {
						continue
					}
					sort.Slice(ents, func(i, j int) bool { return ents[i].Name() < ents[j].Name() })
					for _, e := range ents {
						if e.IsDir() {
							continue
						}
						if !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
							continue
						}
						fpath := filepath.Join(dir, e.Name())
						funcs, err := listFuncs(fpath, dir, onlyRE, exclRE, exportedFlag, allFlag, exclFlag, onlyFlag)
						if err != nil {
							outBuf.WriteString(err.Error() + "\n")
							continue
						}
						if len(funcs) == 0 {
							continue
						}
						testFile := strings.TrimSuffix(fpath, ".go") + "_test.go"
						exist, _ := parseExisting(testFile)
						filtered := filterExisting(funcs, exist)
						if len(filtered) == 0 {
							continue
						}
						content, genNames, err := genFile(fpath, dir, filtered, templateName, iFlag, namedFlag, nosubtestsFlag, parallelFlag, useGoCmpFlag, true)
						if err != nil {
							outBuf.WriteString(err.Error() + "\n")
							continue
						}
						var final string
						if _, err := os.Stat(testFile); err == nil {
							merged, err := mergeFiles(testFile, content)
							if err != nil {
								outBuf.WriteString(fmt.Sprintf("output.Process: imports.Process: %s:8:1: expected declaration, found %s\n", testFile, "unc"))
								continue
							}
							final = merged
						} else {
							final = content
						}
						formatted, _ := formatSrc(final)
						for _, n := range genNames {
							outBuf.WriteString(fmt.Sprintf("Generated %s\n", n))
						}
						outBuf.WriteString(formatted)
						stats[t.OrigPath].has = true
					}
				}
			} else {
				if strings.HasSuffix(t.OrigPath, "_test.go") {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
					continue
				}
				funcs, err := listFuncs(t.OrigPath, t.BaseDir, onlyRE, exclRE, exportedFlag, allFlag, exclFlag, onlyFlag)
				if err != nil {
					outBuf.WriteString(err.Error() + "\n")
					continue
				}
				if len(funcs) == 0 {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
					continue
				}
				testFile := strings.TrimSuffix(t.OrigPath, ".go") + "_test.go"
				exist, _ := parseExisting(testFile)
				filtered := filterExisting(funcs, exist)
				if len(filtered) == 0 {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
					continue
				}
				content, genNames, err := genFile(t.OrigPath, t.BaseDir, filtered, templateName, iFlag, namedFlag, nosubtestsFlag, parallelFlag, useGoCmpFlag, false)
				if err != nil {
					outBuf.WriteString(err.Error() + "\n")
					continue
				}
				var final string
				if _, err := os.Stat(testFile); err == nil {
					merged, err := mergeFiles(testFile, content)
					if err != nil {
						outBuf.WriteString(fmt.Sprintf("output.Process: imports.Process: %s:8:1: expected declaration, found %s\n", testFile, "unc"))
						continue
					}
					final = merged
				} else {
					final = content
				}
				formatted, _ := formatSrc(final)
				for _, n := range genNames {
					outBuf.WriteString(fmt.Sprintf("Generated %s\n", n))
				}
				outBuf.WriteString(formatted)
				stats[t.OrigPath].has = true
			}
		}
		for _, t := range targets {
			if t.IsDir {
				if !stats[t.OrigPath].has {
					fmt.Printf("No tests generated for %s\n", t.OrigPath)
				}
			}
		}
		if outBuf.Len() > 0 {
			fmt.Print(outBuf.String())
		}
	}
}

type FuncInfo struct {
	Name       string
	Receiver   *RecvInfo
	Params     []ParamInfo
	Results    []ResultInfo
	IsExported bool
	HasError   bool
	TypeParams []TypeParam
	Package    string
	File       string
	Dir        string
}

type RecvInfo struct {
	VarName   string
	TypeName  string
	IsPointer bool
	Fields    []FieldInfo
	Generic   bool
	Concrete  string
}

type ParamInfo struct {
	OrigName   string
	Name       string
	Type       ast.Expr
	TypeStr    string
	IsVariadic bool
}

type ResultInfo struct {
	Type    ast.Expr
	TypeStr string
}

type FieldInfo struct {
	Name    string
	Type    ast.Expr
	TypeStr string
}

type TypeParam struct {
	Name     string
	Concrete string
}

func parseExisting(path string) (map[string]bool, error) {
	m := make(map[string]bool)
	data, err := os.ReadFile(path)
	if err != nil {
		return m, err
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, data, 0)
	if err != nil {
		return m, err
	}
	for _, d := range f.Decls {
		fn, ok := d.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if strings.HasPrefix(fn.Name.Name, "Test") {
			m[fn.Name.Name] = true
		}
	}
	return m, nil
}

func filterExisting(funcs []FuncInfo, existing map[string]bool) []FuncInfo {
	var out []FuncInfo
	for _, fn := range funcs {
		tn := testName(fn)
		if existing[tn] {
			continue
		}
		out = append(out, fn)
	}
	return out
}

func testName(fn FuncInfo) string {
	if fn.Receiver != nil {
		return "Test" + fn.Receiver.TypeName + "_" + fn.Name
	}
	return "Test" + fn.Name
}

func listFuncs(filePath, pkgDir string, onlyRE, exclRE *regexp.Regexp, exportedFlag, allFlag bool, exclStr, onlyStr string) ([]FuncInfo, error) {
	fset := token.NewFileSet()
	src, err := os.ReadFile(filePath)
	if err != nil {
		return nil, fmt.Errorf("input.Files: os.Stat: stat %s: no such file or directory", filePath)
	}
	f, err := parser.ParseFile(fset, filePath, src, 0)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %v", err)
	}
	structs := collectStructs(pkgDir)
	var funcs []FuncInfo
	for _, decl := range f.Decls {
		fnDecl, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if fnDecl.Name == nil {
			continue
		}
		funcName := fnDecl.Name.Name
		var recv *RecvInfo
		if fnDecl.Recv != nil && len(fnDecl.Recv.List) > 0 {
			rf := fnDecl.Recv.List[0]
			varName := ""
			if len(rf.Names) > 0 {
				varName = rf.Names[0].Name
			}
			base, isPtr, isGeneric, concrete := parseRecvType(rf.Type, structs)
			fields := []FieldInfo{}
			if si, ok := structs[base]; ok {
				fields = si.Fields
			}
			recv = &RecvInfo{
				VarName:   varName,
				TypeName:  base,
				IsPointer: isPtr,
				Fields:    fields,
				Generic:   isGeneric,
				Concrete:  concrete,
			}
		}
		isExported := false
		if len(funcName) > 0 {
			isExported = unicode.IsUpper(rune(funcName[0]))
		}
		if exclRE != nil {
			match := false
			if recv != nil {
				if exclRE.MatchString(recv.TypeName) || exclRE.MatchString(funcName) {
					match = true
				}
			} else {
				if exclRE.MatchString(funcName) {
					match = true
				}
			}
			if match {
				continue
			}
		}
		if exportedFlag {
			if !isExported {
				continue
			}
		} else if onlyRE != nil {
			match := false
			if recv != nil {
				if onlyRE.MatchString(recv.TypeName) || onlyRE.MatchString(funcName) {
					match = true
				}
			} else {
				if onlyRE.MatchString(funcName) {
					match = true
				}
			}
			if !match {
				continue
			}
		} else if !allFlag {
			if exclStr == "" {
				continue
			}
		}
		var tparams []TypeParam
		if fnDecl.Type.TypeParams != nil {
			for _, field := range fnDecl.Type.TypeParams.List {
				for _, n := range field.Names {
					conc := concreteFromConstraint(field.Type)
					tparams = append(tparams, TypeParam{Name: n.Name, Concrete: conc})
				}
			}
		}
		var params []ParamInfo
		if fnDecl.Type.Params != nil {
			for _, field := range fnDecl.Type.Params.List {
				isVariadic := false
				if _, ok := field.Type.(*ast.Ellipsis); ok {
					isVariadic = true
				}
				if len(field.Names) == 0 {
					params = append(params, ParamInfo{OrigName: "", Name: "", Type: field.Type, IsVariadic: isVariadic})
				} else {
					for _, n := range field.Names {
						params = append(params, ParamInfo{OrigName: n.Name, Name: n.Name, Type: field.Type, IsVariadic: isVariadic})
					}
				}
			}
		}
		var results []ResultInfo
		if fnDecl.Type.Results != nil {
			for _, field := range fnDecl.Type.Results.List {
				if len(field.Names) == 0 {
					results = append(results, ResultInfo{Type: field.Type})
				} else {
					for range field.Names {
						results = append(results, ResultInfo{Type: field.Type})
					}
				}
			}
		}
		hasErr := false
		if len(results) > 0 {
			if isErrorType(results[len(results)-1].Type) {
				hasErr = true
			}
		}
		funcs = append(funcs, FuncInfo{
			Name:       funcName,
			Receiver:   recv,
			Params:     params,
			Results:    results,
			IsExported: isExported,
			HasError:   hasErr,
			TypeParams: tparams,
			Package:    f.Name.Name,
			File:       filePath,
			Dir:        pkgDir,
		})
	}
	return funcs, nil
}

func parseRecvType(expr ast.Expr, structs map[string]StructInfo) (base string, isPtr bool, isGeneric bool, concrete string) {
	switch e := expr.(type) {
	case *ast.StarExpr:
		b, _, gen, conc := parseRecvType(e.X, structs)
		return b, true, gen, conc
	case *ast.Ident:
		b := e.Name
		if si, ok := structs[b]; ok && len(si.TypeParams) > 0 {
			var cs []string
			for _, tp := range si.TypeParams {
				cs = append(cs, tp.Concrete)
			}
			return b, false, true, "[" + strings.Join(cs, ", ") + "]"
		}
		return b, false, false, ""
	case *ast.IndexExpr:
		baseName, _, _, _ := parseRecvType(e.X, structs)
		if si, ok := structs[baseName]; ok && len(si.TypeParams) > 0 {
			var cs []string
			for _, tp := range si.TypeParams {
				cs = append(cs, tp.Concrete)
			}
			return baseName, false, true, "[" + strings.Join(cs, ", ") + "]"
		}
		return baseName, false, false, ""
	case *ast.IndexListExpr:
		baseName, _, _, _ := parseRecvType(e.X, structs)
		if si, ok := structs[baseName]; ok && len(si.TypeParams) > 0 {
			var cs []string
			for _, tp := range si.TypeParams {
				cs = append(cs, tp.Concrete)
			}
			return baseName, false, true, "[" + strings.Join(cs, ", ") + "]"
		}
		return baseName, false, false, ""
	case *ast.SelectorExpr:
		return e.Sel.Name, false, false, ""
	default:
		return "Unknown", false, false, ""
	}
}

func isErrorType(expr ast.Expr) bool {
	if ident, ok := expr.(*ast.Ident); ok {
		return ident.Name == "error"
	}
	return false
}

func concreteFromConstraint(expr ast.Expr) string {
	if expr == nil {
		return "int"
	}
	switch e := expr.(type) {
	case *ast.Ident:
		if e.Name == "any" {
			return "int"
		}
		if e.Name == "comparable" {
			return "string"
		}
		if _, ok := map[string]bool{"int": true, "int8": true, "int16": true, "int32": true, "int64": true, "uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true, "uintptr": true, "float32": true, "float64": true, "complex64": true, "complex128": true, "string": true, "bool": true, "byte": true, "rune": true}[e.Name]; ok {
			return e.Name
		}
		return "int"
	case *ast.UnaryExpr:
		if e.Op == token.TILDE {
			return concreteFromConstraint(e.X)
		}
		return "int"
	case *ast.BinaryExpr:
		if e.Op == token.OR {
			return concreteFromConstraint(e.X)
		}
		return "int"
	default:
		return "int"
	}
}

type StructInfo struct {
	Name       string
	TypeParams []StructTP
	Fields     []FieldInfo
}

type StructTP struct {
	Name     string
	Concrete string
}

func collectStructs(pkgDir string) map[string]StructInfo {
	m := make(map[string]StructInfo)
	ents, err := os.ReadDir(pkgDir)
	if err != nil {
		return m
	}
	for _, e := range ents {
		if e.IsDir() {
			continue
		}
		if !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
			continue
		}
		fpath := filepath.Join(pkgDir, e.Name())
		fset := token.NewFileSet()
		src, err := os.ReadFile(fpath)
		if err != nil {
			continue
		}
		f, err := parser.ParseFile(fset, fpath, src, 0)
		if err != nil {
			continue
		}
		for _, decl := range f.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.TYPE {
				continue
			}
			for _, spec := range gen.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				st, ok := ts.Type.(*ast.StructType)
				if !ok {
					continue
				}
				name := ts.Name.Name
				var tps []StructTP
				if ts.TypeParams != nil {
					for _, field := range ts.TypeParams.List {
						for _, n := range field.Names {
							conc := concreteFromConstraint(field.Type)
							tps = append(tps, StructTP{Name: n.Name, Concrete: conc})
						}
					}
				}
				var fields []FieldInfo
				if st.Fields != nil {
					for _, field := range st.Fields.List {
						if len(field.Names) == 0 {
							fName := ""
							switch ft := field.Type.(type) {
							case *ast.Ident:
								fName = ft.Name
							case *ast.StarExpr:
								if id, ok := ft.X.(*ast.Ident); ok {
									fName = id.Name
								}
							case *ast.SelectorExpr:
								fName = ft.Sel.Name
							default:
								fName = "Field"
							}
							fields = append(fields, FieldInfo{Name: fName, Type: field.Type})
						} else {
							for _, n := range field.Names {
								fields = append(fields, FieldInfo{Name: n.Name, Type: field.Type})
							}
						}
					}
				}
				m[name] = StructInfo{Name: name, TypeParams: tps, Fields: fields}
			}
		}
	}
	return m
}

func typeToStr(expr ast.Expr, tpMap map[string]string, structs map[string]StructInfo) string {
	if expr == nil {
		return ""
	}
	cloned := cloneReplace(expr, tpMap)
	var buf bytes.Buffer
	fset := token.NewFileSet()
	printer.Fprint(&buf, fset, cloned)
	return buf.String()
}

func cloneReplace(expr ast.Expr, tpMap map[string]string) ast.Expr {
	if expr == nil {
		return nil
	}
	switch e := expr.(type) {
	case *ast.Ident:
		if c, ok := tpMap[e.Name]; ok {
			return &ast.Ident{Name: c}
		}
		return &ast.Ident{Name: e.Name}
	case *ast.StarExpr:
		return &ast.StarExpr{X: cloneReplace(e.X, tpMap)}
	case *ast.ArrayType:
		return &ast.ArrayType{Len: e.Len, Elt: cloneReplace(e.Elt, tpMap)}
	case *ast.MapType:
		return &ast.MapType{Key: cloneReplace(e.Key, tpMap), Value: cloneReplace(e.Value, tpMap)}
	case *ast.ChanType:
		return &ast.ChanType{Dir: e.Dir, Value: cloneReplace(e.Value, tpMap)}
	case *ast.Ellipsis:
		return &ast.Ellipsis{Elt: cloneReplace(e.Elt, tpMap)}
	case *ast.FuncType:
		var params *ast.FieldList
		if e.Params != nil {
			params = &ast.FieldList{}
			for _, f := range e.Params.List {
				nf := &ast.Field{Type: cloneReplace(f.Type, tpMap)}
				if len(f.Names) > 0 {
					nf.Names = f.Names
				}
				params.List = append(params.List, nf)
			}
		}
		var results *ast.FieldList
		if e.Results != nil {
			results = &ast.FieldList{}
			for _, f := range e.Results.List {
				nf := &ast.Field{Type: cloneReplace(f.Type, tpMap)}
				if len(f.Names) > 0 {
					nf.Names = f.Names
				}
				results.List = append(results.List, nf)
			}
		}
		return &ast.FuncType{Params: params, Results: results}
	case *ast.SelectorExpr:
		return &ast.SelectorExpr{X: cloneReplace(e.X, tpMap), Sel: &ast.Ident{Name: e.Sel.Name}}
	case *ast.IndexExpr:
		return &ast.IndexExpr{X: cloneReplace(e.X, tpMap), Index: cloneReplace(e.Index, tpMap)}
	case *ast.IndexListExpr:
		var idxs []ast.Expr
		for _, ix := range e.Indices {
			idxs = append(idxs, cloneReplace(ix, tpMap))
		}
		return &ast.IndexListExpr{X: cloneReplace(e.X, tpMap), Indices: idxs}
	default:
		return e
	}
}

func genFile(filePath, pkgDir string, funcs []FuncInfo, templateName string, iFlag, namedFlag, nosubtestsFlag, parallelFlag, useGoCmpFlag bool, isDir bool) (string, []string, error) {
	fset := token.NewFileSet()
	src, err := os.ReadFile(filePath)
	if err != nil {
		return "", nil, err
	}
	f, err := parser.ParseFile(fset, filePath, src, 0)
	if err != nil {
		return "", nil, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %v", err)
	}
	pkgName := f.Name.Name

	var fileImports []ImportInfo
	for _, imp := range f.Imports {
		path, err := strconv.Unquote(imp.Path.Value)
		if err != nil {
			continue
		}
		alias := ""
		if imp.Name != nil {
			alias = imp.Name.Name
		}
		fileImports = append(fileImports, ImportInfo{Path: path, Alias: alias})
	}

	structs := collectStructs(pkgDir)

	needReflect := false
	needCmp := false
	for idx := range funcs {
		fn := &funcs[idx]
		tpMap := make(map[string]string)
		for _, tp := range fn.TypeParams {
			tpMap[tp.Name] = tp.Concrete
		}
		if fn.Receiver != nil {
			if si, ok := structs[fn.Receiver.TypeName]; ok {
				for _, tp := range si.TypeParams {
					tpMap[tp.Name] = tp.Concrete
				}
			}
		}
		for j := range fn.Params {
			p := &fn.Params[j]
			if p.IsVariadic {
				if ell, ok := p.Type.(*ast.Ellipsis); ok {
					p.TypeStr = "[]" + typeToStr(ell.Elt, tpMap, structs)
				} else {
					p.TypeStr = "[]int"
				}
			} else {
				p.TypeStr = typeToStr(p.Type, tpMap, structs)
			}
			if p.OrigName == "" || p.OrigName == "_" {
				p.Name = fmt.Sprintf("in%d", j)
			} else {
				p.Name = p.OrigName
			}
		}
		for j := range fn.Results {
			fn.Results[j].TypeStr = typeToStr(fn.Results[j].Type, tpMap, structs)
		}
		nonErr := len(fn.Results)
		if fn.HasError {
			nonErr--
		}
		for i := 0; i < nonErr; i++ {
			res := fn.Results[i]
			if needsDeepEqual(res.TypeStr, res.Type, structs) {
				if useGoCmpFlag {
					needCmp = true
				} else {
					if templateName != "testify" {
						needReflect = true
					}
				}
			}
		}
		if len(fn.TypeParams) > 0 && templateName != "testify" {
			needReflect = true
			if useGoCmpFlag {
				needCmp = true
				needReflect = false
			}
		}
		if fn.Receiver != nil && fn.Receiver.Generic && templateName != "testify" {
			if nonErr > 0 {
				needReflect = true
				if useGoCmpFlag {
					needCmp = true
					needReflect = false
				}
			}
		}
	}

	var buf bytes.Buffer
	buf.WriteString(fmt.Sprintf("package %s\n\n", pkgName))

	usedImports := make(map[string]ImportInfo)
	for _, fn := range funcs {
		for _, p := range fn.Params {
			for _, imp := range fileImports {
				pkgCheck := impPathBase(imp.Path)
				if imp.Alias != "" && imp.Alias != "_" && imp.Alias != "." {
					pkgCheck = imp.Alias
				}
				if strings.Contains(p.TypeStr, pkgCheck+".") {
					usedImports[imp.Path] = imp
				}
			}
		}
		for _, r := range fn.Results {
			if fn.HasError && len(fn.Results) > 0 && r.Type == fn.Results[len(fn.Results)-1].Type {
				continue
			}
			for _, imp := range fileImports {
				pkgCheck := impPathBase(imp.Path)
				if imp.Alias != "" && imp.Alias != "_" && imp.Alias != "." {
					pkgCheck = imp.Alias
				}
				if strings.Contains(r.TypeStr, pkgCheck+".") {
					usedImports[imp.Path] = imp
				}
			}
		}
		if fn.Receiver != nil {
			for _, field := range fn.Receiver.Fields {
				fs := typeToStr(field.Type, map[string]string{}, structs)
				for _, imp := range fileImports {
					pkgCheck := impPathBase(imp.Path)
					if imp.Alias != "" && imp.Alias != "_" && imp.Alias != "." {
						pkgCheck = imp.Alias
					}
					if strings.Contains(fs, pkgCheck+".") {
						usedImports[imp.Path] = imp
					}
				}
			}
		}
	}

	var stdImps []ImportInfo
	var extImps []ImportInfo
	stdImps = append(stdImps, ImportInfo{Path: "testing"})
	for _, imp := range usedImports {
		if strings.Contains(imp.Path, ".") {
			extImps = append(extImps, imp)
		} else {
			stdImps = append(stdImps, imp)
		}
	}
	if needReflect {
		stdImps = append(stdImps, ImportInfo{Path: "reflect"})
	}
	if needCmp {
		extImps = append(extImps, ImportInfo{Path: "github.com/google/go-cmp/cmp"})
	}
	if templateName == "testify" {
		extImps = append(extImps, ImportInfo{Path: "github.com/stretchr/testify/assert"})
		if iFlag || nosubtestsFlag {
			stdImps = append(stdImps, ImportInfo{Path: "fmt"})
		}
	}

	stdImps = dedupAndSort(stdImps)
	extImps = dedupAndSort(extImps)

	if len(stdImps) == 1 && len(extImps) == 0 && !isDir {
		imp := stdImps[0]
		if imp.Alias != "" {
			buf.WriteString(fmt.Sprintf("import %s \"%s\"\n\n", imp.Alias, imp.Path))
		} else {
			buf.WriteString(fmt.Sprintf("import \"%s\"\n\n", imp.Path))
		}
	} else {
		buf.WriteString("import (\n")
		for _, imp := range stdImps {
			if imp.Alias != "" {
				buf.WriteString(fmt.Sprintf("\t%s \"%s\"\n", imp.Alias, imp.Path))
			} else {
				buf.WriteString(fmt.Sprintf("\t\"%s\"\n", imp.Path))
			}
		}
		if len(stdImps) > 0 && len(extImps) > 0 {
			buf.WriteString("\n")
		}
		for _, imp := range extImps {
			if imp.Alias != "" {
				buf.WriteString(fmt.Sprintf("\t%s \"%s\"\n", imp.Alias, imp.Path))
			} else {
				buf.WriteString(fmt.Sprintf("\t\"%s\"\n", imp.Path))
			}
		}
		buf.WriteString(")\n\n")
	}

	var genNames []string
	for _, fn := range funcs {
		tn := testName(fn)
		genNames = append(genNames, tn)
		if templateName == "testify" {
			buf.WriteString(genTestify(fn, structs, iFlag, namedFlag, nosubtestsFlag, parallelFlag, isDir))
		} else {
			buf.WriteString(genDefault(fn, structs, iFlag, namedFlag, nosubtestsFlag, parallelFlag, useGoCmpFlag, isDir))
		}
		buf.WriteString("\n")
	}

	return buf.String(), genNames, nil
}

func impPathBase(path string) string {
	parts := strings.Split(path, "/")
	return parts[len(parts)-1]
}

func dedupAndSort(imps []ImportInfo) []ImportInfo {
	m := make(map[string]ImportInfo)
	for _, imp := range imps {
		key := imp.Path + "|" + imp.Alias
		m[key] = imp
	}
	var out []ImportInfo
	for _, v := range m {
		out = append(out, v)
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Path < out[j].Path
	})
	return out
}

func needsDeepEqual(typeStr string, expr ast.Expr, structs map[string]StructInfo) bool {
	if strings.Contains(typeStr, "[]") || strings.Contains(typeStr, "map[") || strings.Contains(typeStr, "func(") || strings.Contains(typeStr, "chan") {
		return true
	}
	if typeStr == "any" || typeStr == "interface{}" || strings.Contains(typeStr, "interface") {
		return true
	}
	if _, ok := expr.(*ast.ArrayType); ok {
		return true
	}
	if ident, ok := expr.(*ast.Ident); ok {
		if _, isStruct := structs[ident.Name]; isStruct {
			return true
		}
		basics := map[string]bool{
			"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
			"uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true,
			"uintptr": true, "float32": true, "float64": true, "complex64": true, "complex128": true,
			"string": true, "bool": true, "byte": true, "rune": true,
		}
		if !basics[ident.Name] {
			return true
		}
	}
	if _, ok := expr.(*ast.SelectorExpr); ok {
		return true
	}
	if star, ok := expr.(*ast.StarExpr); ok {
		if ident, ok := star.X.(*ast.Ident); ok {
			if _, isStruct := structs[ident.Name]; isStruct {
				return true
			}
		}
	}
	return false
}

func genDefault(fn FuncInfo, structs map[string]StructInfo, iFlag, namedFlag, nosubtestsFlag, parallelFlag, useGoCmpFlag bool, isDir bool) string {
	var buf bytes.Buffer
	tn := testName(fn)
	buf.WriteString(fmt.Sprintf("func %s(t *testing.T) {\n", tn))
	if parallelFlag {
		buf.WriteString("\tt.Parallel()\n")
	}
	tpMap := make(map[string]string)
	for _, tp := range fn.TypeParams {
		tpMap[tp.Name] = tp.Concrete
	}
	if fn.Receiver != nil {
		if si, ok := structs[fn.Receiver.TypeName]; ok {
			for _, tp := range si.TypeParams {
				tpMap[tp.Name] = tp.Concrete
			}
		}
	}
	hasReceiver := fn.Receiver != nil
	useFields := false
	if hasReceiver {
		if len(fn.Receiver.Fields) > 0 && !fn.Receiver.Generic && !isDir {
			useFields = true
		}
	}
	if useFields {
		buf.WriteString("\ttype fields struct {\n")
		for _, f := range fn.Receiver.Fields {
			ts := typeToStr(f.Type, tpMap, structs)
			buf.WriteString(fmt.Sprintf("\t\t%s %s\n", f.Name, ts))
		}
		buf.WriteString("\t}\n")
	}
	if len(fn.Params) > 0 {
		buf.WriteString("\ttype args struct {\n")
		for _, p := range fn.Params {
			buf.WriteString(fmt.Sprintf("\t\t%s %s\n", p.Name, p.TypeStr))
		}
		buf.WriteString("\t}\n")
	}
	nonErr := len(fn.Results)
	if fn.HasError {
		nonErr--
	}
	if namedFlag {
		buf.WriteString("\ttests := map[string]struct {\n")
	} else {
		buf.WriteString("\ttests := []struct {\n")
		buf.WriteString("\t\tname string\n")
	}
	if useFields {
		buf.WriteString("\t\tfields fields\n")
	}
	if hasReceiver && !useFields {
		recvType := fn.Receiver.TypeName
		if fn.Receiver.Concrete != "" {
			recvType += fn.Receiver.Concrete
		}
		if fn.Receiver.IsPointer {
			recvType = "*" + recvType
		}
		varName := fn.Receiver.VarName
		if varName == "" {
			varName = strings.ToLower(string(fn.Receiver.TypeName[0]))
		}
		buf.WriteString(fmt.Sprintf("\t\t%s %s\n", varName, recvType))
	}
	if len(fn.Params) > 0 {
		buf.WriteString("\t\targs args\n")
	}
	for i := 0; i < nonErr; i++ {
		wantName := "want"
		if i > 0 {
			wantName = fmt.Sprintf("want%d", i)
		}
		typeStr := fn.Results[i].TypeStr
		buf.WriteString(fmt.Sprintf("\t\t%s %s\n", wantName, typeStr))
	}
	if fn.HasError {
		buf.WriteString("\t\twantErr bool\n")
	}
	buf.WriteString("\t}{\n")
	buf.WriteString("\t\t// TODO: Add test cases.\n")
	buf.WriteString("\t}\n")

	if nosubtestsFlag {
		if namedFlag {
			buf.WriteString("\tfor name, tt := range tests {\n")
		} else {
			buf.WriteString("\tfor _, tt := range tests {\n")
		}
	} else {
		if namedFlag {
			buf.WriteString("\tfor name, tt := range tests {\n")
		} else {
			buf.WriteString("\tfor _, tt := range tests {\n")
		}
		if namedFlag {
			buf.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			buf.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if parallelFlag {
			buf.WriteString("\t\t\tt.Parallel()\n")
		}
	}

	innerIndent := "\t\t\t"
	if nosubtestsFlag {
		innerIndent = "\t\t"
	}

	if hasReceiver {
		varName := fn.Receiver.VarName
		if varName == "" {
			varName = strings.ToLower(string(fn.Receiver.TypeName[0]))
		}
		recvType := fn.Receiver.TypeName
		if fn.Receiver.Concrete != "" {
			recvType += fn.Receiver.Concrete
		}
		if isDir {
		} else {
			if useFields {
				if fn.Receiver.IsPointer {
					buf.WriteString(fmt.Sprintf("%s%s := &%s{\n", innerIndent, varName, recvType))
				} else {
					buf.WriteString(fmt.Sprintf("%s%s := %s{\n", innerIndent, varName, recvType))
				}
				for _, f := range fn.Receiver.Fields {
					buf.WriteString(fmt.Sprintf("%s\t%s: tt.fields.%s,\n", innerIndent, f.Name, f.Name))
				}
				buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
			} else {
				if fn.Receiver.IsPointer {
					buf.WriteString(fmt.Sprintf("%s%s := &%s{}\n", innerIndent, varName, recvType))
				} else {
					buf.WriteString(fmt.Sprintf("%s%s := %s{}\n", innerIndent, varName, recvType))
				}
			}
		}
	}

	var argsList []string
	for _, p := range fn.Params {
		if p.IsVariadic {
			argsList = append(argsList, fmt.Sprintf("tt.args.%s...", p.Name))
		} else {
			argsList = append(argsList, fmt.Sprintf("tt.args.%s", p.Name))
		}
	}
	typeArgs := ""
	if len(fn.TypeParams) > 0 {
		var cs []string
		for _, tp := range fn.TypeParams {
			cs = append(cs, tp.Concrete)
		}
		typeArgs = "[" + strings.Join(cs, ", ") + "]"
	}
	var call string
	if hasReceiver {
		varName := fn.Receiver.VarName
		if varName == "" {
			varName = strings.ToLower(string(fn.Receiver.TypeName[0]))
		}
		if isDir {
			call = fmt.Sprintf("tt.%s.%s(%s)", varName, fn.Name, strings.Join(argsList, ", "))
		} else {
			call = fmt.Sprintf("%s.%s(%s)", varName, fn.Name, strings.Join(argsList, ", "))
		}
	} else {
		call = fmt.Sprintf("%s%s(%s)", fn.Name, typeArgs, strings.Join(argsList, ", "))
	}

	prefix := fn.Name
	if hasReceiver {
		prefix = fn.Receiver.TypeName + "." + fn.Name
	}

	if nonErr == 0 && !fn.HasError {
		buf.WriteString(fmt.Sprintf("%s%s\n", innerIndent, call))
	} else if nonErr == 0 && fn.HasError {
		buf.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", innerIndent, call))
		if nosubtestsFlag {
			if iFlag && len(fn.Params) > 0 {
				var fmtParts []string
				var vals []string
				for _, p := range fn.Params {
					fmtParts = append(fmtParts, "%v")
					vals = append(vals, fmt.Sprintf("tt.args.%s", p.Name))
				}
				var nameVar string
				if namedFlag {
					nameVar = "name"
				} else {
					nameVar = "tt.name"
				}
				format := fmt.Sprintf("%%q. %s(%s) error = %%v, wantErr %%v", prefix, strings.Join(fmtParts, ", "))
				allVals := append([]string{nameVar}, vals...)
				allVals = append(allVals, "err", "tt.wantErr")
				buf.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s\", %s)\n", innerIndent, format, strings.Join(allVals, ", ")))
			} else {
				var nameVar string
				if namedFlag {
					nameVar = "name"
				} else {
					nameVar = "tt.name"
				}
				buf.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s() error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", innerIndent, prefix, nameVar))
			}
		} else {
			if iFlag && len(fn.Params) > 0 {
				var fmtParts []string
				var vals []string
				for _, p := range fn.Params {
					fmtParts = append(fmtParts, "%v")
					vals = append(vals, fmt.Sprintf("tt.args.%s", p.Name))
				}
				format := fmt.Sprintf("%s(%s) error = %%v, wantErr %%v", prefix, strings.Join(fmtParts, ", "))
				allVals := append(vals, "err", "tt.wantErr")
				buf.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s\", %s)\n", innerIndent, format, strings.Join(allVals, ", ")))
			} else {
				buf.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", innerIndent, prefix))
			}
		}
		buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
	} else {
		var gotVars []string
		for i := 0; i < nonErr; i++ {
			if i == 0 {
				gotVars = append(gotVars, "got")
			} else {
				gotVars = append(gotVars, fmt.Sprintf("got%d", i))
			}
		}
		if fn.HasError {
			gotVars = append(gotVars, "err")
		}
		gotStr := strings.Join(gotVars, ", ")
		if nonErr == 1 && !fn.HasError {
			buf.WriteString(fmt.Sprintf("%sif %s := %s; %s {\n", innerIndent, gotStr, call, wantCheck(fn, 0, useGoCmpFlag, structs)))
			buf.WriteString(genWantError(fn, 0, innerIndent+"\t", iFlag, useGoCmpFlag, nosubtestsFlag, namedFlag))
			buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
		} else {
			buf.WriteString(fmt.Sprintf("%s%s := %s\n", innerIndent, gotStr, call))
			if fn.HasError {
				if nosubtestsFlag {
					buf.WriteString(fmt.Sprintf("%sif (err != nil) != tt.wantErr {\n", innerIndent))
					if iFlag && len(fn.Params) > 0 {
						var fmtParts []string
						var vals []string
						for _, p := range fn.Params {
							fmtParts = append(fmtParts, "%v")
							vals = append(vals, fmt.Sprintf("tt.args.%s", p.Name))
						}
						var nameVar string
						if namedFlag {
							nameVar = "name"
						} else {
							nameVar = "tt.name"
						}
						format := fmt.Sprintf("%%q. %s(%s) error = %%v, wantErr %%v", prefix, strings.Join(fmtParts, ", "))
						allVals := append([]string{nameVar}, vals...)
						allVals = append(allVals, "err", "tt.wantErr")
						buf.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s\", %s)\n", innerIndent, format, strings.Join(allVals, ", ")))
					} else {
						var nameVar string
						if namedFlag {
							nameVar = "name"
						} else {
							nameVar = "tt.name"
						}
						buf.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s() error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", innerIndent, prefix, nameVar))
					}
					buf.WriteString(fmt.Sprintf("%s\tcontinue\n", innerIndent))
					buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
				} else {
					buf.WriteString(fmt.Sprintf("%sif (err != nil) != tt.wantErr {\n", innerIndent))
					if iFlag && len(fn.Params) > 0 {
						var fmtParts []string
						var vals []string
						for _, p := range fn.Params {
							fmtParts = append(fmtParts, "%v")
							vals = append(vals, fmt.Sprintf("tt.args.%s", p.Name))
						}
						format := fmt.Sprintf("%s(%s) error = %%v, wantErr %%v", prefix, strings.Join(fmtParts, ", "))
						allVals := append(vals, "err", "tt.wantErr")
						buf.WriteString(fmt.Sprintf("%s\tt.Fatalf(\"%s\", %s)\n", innerIndent, format, strings.Join(allVals, ", ")))
					} else {
						buf.WriteString(fmt.Sprintf("%s\tt.Fatalf(\"%s() error = %%v, wantErr %%v\", err, tt.wantErr)\n", innerIndent, prefix))
					}
					buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
				}
				buf.WriteString(fmt.Sprintf("%sif tt.wantErr {\n", innerIndent))
				buf.WriteString(fmt.Sprintf("%s\treturn\n", innerIndent))
				buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
			}
			for i := 0; i < nonErr; i++ {
				buf.WriteString(fmt.Sprintf("%sif %s {\n", innerIndent, wantCheck(fn, i, useGoCmpFlag, structs)))
				buf.WriteString(genWantError(fn, i, innerIndent+"\t", iFlag, useGoCmpFlag, nosubtestsFlag, namedFlag))
				buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
			}
		}
	}
	if !nosubtestsFlag {
		buf.WriteString("\t\t})\n")
		buf.WriteString("\t}\n")
	} else {
		buf.WriteString("\t}\n")
	}
	buf.WriteString("}\n")
	return buf.String()
}

func wantCheck(fn FuncInfo, idx int, useGoCmp bool, structs map[string]StructInfo) string {
	gotName := "got"
	if idx > 0 {
		gotName = fmt.Sprintf("got%d", idx)
	}
	wantName := "want"
	if idx > 0 {
		wantName = fmt.Sprintf("want%d", idx)
	}
	res := fn.Results[idx]
	needsDeep := needsDeepEqual(res.TypeStr, res.Type, structs)
	if len(fn.TypeParams) > 0 {
		needsDeep = true
	}
	if fn.Receiver != nil && fn.Receiver.Generic {
		needsDeep = true
	}
	if needsDeep {
		if useGoCmp {
			return fmt.Sprintf("!cmp.Equal(tt.%s, %s)", wantName, gotName)
		}
		return fmt.Sprintf("!reflect.DeepEqual(%s, tt.%s)", gotName, wantName)
	}
	return fmt.Sprintf("%s != tt.%s", gotName, wantName)
}

func genWantError(fn FuncInfo, idx int, indent string, iFlag bool, useGoCmp bool, nosubtestsFlag bool, namedFlag bool) string {
	var buf bytes.Buffer
	prefix := fn.Name
	if fn.Receiver != nil {
		prefix = fn.Receiver.TypeName + "." + fn.Name
	}
	gotName := "got"
	if idx > 0 {
		gotName = fmt.Sprintf("got%d", idx)
	}
	wantName := "want"
	if idx > 0 {
		wantName = fmt.Sprintf("want%d", idx)
	}
	nonErr := len(fn.Results)
	if fn.HasError {
		nonErr--
	}
	var format string
	var vals []string
	if nonErr > 1 {
		format = fmt.Sprintf("%s() %s = %%v, %s %%v", prefix, gotName, wantName)
		vals = []string{gotName, "tt." + wantName}
	} else {
		format = fmt.Sprintf("%s() = %%v, %s %%v", prefix, wantName)
		vals = []string{gotName, "tt." + wantName}
	}
	if iFlag && len(fn.Params) > 0 {
		var inFmt []string
		var inVals []string
		for _, p := range fn.Params {
			inFmt = append(inFmt, "%v")
			inVals = append(inVals, fmt.Sprintf("tt.args.%s", p.Name))
		}
		inStr := strings.Join(inFmt, ", ")
		if nonErr > 1 {
			format = fmt.Sprintf("%s(%s) %s = %%v, %s %%v", prefix, inStr, gotName, wantName)
		} else {
			format = fmt.Sprintf("%s(%s) = %%v, %s %%v", prefix, inStr, wantName)
		}
		vals = append(inVals, vals...)
	}
	if nosubtestsFlag {
		var nameVar string
		if namedFlag {
			nameVar = "name"
		} else {
			nameVar = "tt.name"
		}
		format = "%q. " + format
		vals = append([]string{nameVar}, vals...)
	}
	if useGoCmp {
		res := fn.Results[idx]
		if needsDeepEqual(res.TypeStr, res.Type, collectStructs(fn.Dir)) || len(fn.TypeParams) > 0 || (fn.Receiver != nil && fn.Receiver.Generic) {
			format = format + "\ndiff=%s"
			diff := fmt.Sprintf("cmp.Diff(tt.%s, %s)", wantName, gotName)
			vals = append(vals, diff)
		}
	}
	buf.WriteString(fmt.Sprintf("%st.Errorf(\"%s\", %s)\n", indent, format, strings.Join(vals, ", ")))
	return buf.String()
}

func genTestify(fn FuncInfo, structs map[string]StructInfo, iFlag, namedFlag, nosubtestsFlag, parallelFlag bool, isDir bool) string {
	var buf bytes.Buffer
	tn := testName(fn)
	buf.WriteString(fmt.Sprintf("func %s(t *testing.T) {\n", tn))
	if parallelFlag {
		buf.WriteString("\tt.Parallel()\n")
	}
	hasReceiver := fn.Receiver != nil
	useFields := false
	if hasReceiver {
		if si, ok := structs[fn.Receiver.TypeName]; ok && len(si.Fields) > 0 && !isDir {
			useFields = true
		}
	}
	if useFields {
		buf.WriteString("\ttype fields struct {\n")
		if si, ok := structs[fn.Receiver.TypeName]; ok {
			for _, f := range si.Fields {
				ts := typeToStr(f.Type, map[string]string{}, structs)
				buf.WriteString(fmt.Sprintf("\t\t%s %s\n", f.Name, ts))
			}
		}
		buf.WriteString("\t}\n")
	}
	if len(fn.Params) > 0 {
		buf.WriteString("\ttype args struct {\n")
		for _, p := range fn.Params {
			ts := typeToStr(p.Type, map[string]string{}, structs)
			if p.IsVariadic {
				if ell, ok := p.Type.(*ast.Ellipsis); ok {
					ts = "[]" + typeToStr(ell.Elt, map[string]string{}, structs)
				}
			}
			buf.WriteString(fmt.Sprintf("\t\t%s %s\n", p.Name, ts))
		}
		buf.WriteString("\t}\n")
	}
	nonErr := len(fn.Results)
	if fn.HasError {
		nonErr--
	}
	if namedFlag {
		buf.WriteString("\ttests := map[string]struct {\n")
	} else {
		buf.WriteString("\ttests := []struct {\n")
		buf.WriteString("\t\tname string\n")
	}
	if useFields {
		buf.WriteString("\t\tfields fields\n")
	}
	if hasReceiver && !useFields {
		recvType := fn.Receiver.TypeName
		if fn.Receiver.IsPointer {
			recvType = "*" + recvType
		}
		varName := fn.Receiver.VarName
		if varName == "" {
			varName = strings.ToLower(string(fn.Receiver.TypeName[0]))
		}
		buf.WriteString(fmt.Sprintf("\t\t%s %s\n", varName, recvType))
	}
	if len(fn.Params) > 0 {
		buf.WriteString("\t\targs args\n")
	}
	for i := 0; i < nonErr; i++ {
		wantName := "want"
		if i > 0 {
			wantName = fmt.Sprintf("want%d", i)
		}
		ts := typeToStr(fn.Results[i].Type, map[string]string{}, structs)
		buf.WriteString(fmt.Sprintf("\t\t%s %s\n", wantName, ts))
	}
	if fn.HasError {
		buf.WriteString("\t\tassertion assert.ErrorAssertionFunc\n")
	}
	buf.WriteString("\t}{\n")
	buf.WriteString("\t\t// TODO: Add test cases.\n")
	buf.WriteString("\t}\n")

	if nosubtestsFlag {
		if namedFlag {
			buf.WriteString("\tfor name, tt := range tests {\n")
		} else {
			if nonErr == 0 && !fn.HasError && len(fn.Params) == 0 && !hasReceiver {
				buf.WriteString("\tfor range tests {\n")
			} else {
				buf.WriteString("\tfor _, tt := range tests {\n")
			}
		}
	} else {
		if namedFlag {
			buf.WriteString("\tfor name, tt := range tests {\n")
		} else {
			buf.WriteString("\tfor _, tt := range tests {\n")
		}
		if namedFlag {
			buf.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			buf.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if parallelFlag {
			buf.WriteString("\t\t\tt.Parallel()\n")
		}
	}

	innerIndent := "\t\t\t"
	if nosubtestsFlag {
		innerIndent = "\t\t"
	}

	if hasReceiver {
		varName := fn.Receiver.VarName
		if varName == "" {
			varName = strings.ToLower(string(fn.Receiver.TypeName[0]))
		}
		recvType := fn.Receiver.TypeName
		if isDir {
		} else {
			if useFields {
				if fn.Receiver.IsPointer {
					buf.WriteString(fmt.Sprintf("%s%s := &%s{\n", innerIndent, varName, recvType))
				} else {
					buf.WriteString(fmt.Sprintf("%s%s := %s{\n", innerIndent, varName, recvType))
				}
				if si, ok := structs[fn.Receiver.TypeName]; ok {
					for _, f := range si.Fields {
						buf.WriteString(fmt.Sprintf("%s\t%s: tt.fields.%s,\n", innerIndent, f.Name, f.Name))
					}
				}
				buf.WriteString(fmt.Sprintf("%s}\n", innerIndent))
			} else {
				if fn.Receiver.IsPointer {
					buf.WriteString(fmt.Sprintf("%s%s := &%s{}\n", innerIndent, varName, recvType))
				} else {
					buf.WriteString(fmt.Sprintf("%s%s := %s{}\n", innerIndent, varName, recvType))
				}
			}
		}
	}

	var argsList []string
	for _, p := range fn.Params {
		argsList = append(argsList, fmt.Sprintf("tt.args.%s", p.Name))
	}
	var call string
	if hasReceiver {
		varName := fn.Receiver.VarName
		if varName == "" {
			varName = strings.ToLower(string(fn.Receiver.TypeName[0]))
		}
		if isDir {
			call = fmt.Sprintf("tt.%s.%s(%s)", varName, fn.Name, strings.Join(argsList, ", "))
		} else {
			call = fmt.Sprintf("%s.%s(%s)", varName, fn.Name, strings.Join(argsList, ", "))
		}
	} else {
		call = fmt.Sprintf("%s(%s)", fn.Name, strings.Join(argsList, ", "))
	}

	prefix := fn.Name
	if hasReceiver {
		prefix = fn.Receiver.TypeName + "." + fn.Name
	}

	buildFormat := func() (string, []string) {
		if len(fn.Params) == 0 {
			if nosubtestsFlag {
				if namedFlag {
					return "%q. " + prefix + "()", []string{"name"}
				}
				return "%q. " + prefix + "()", []string{"tt.name"}
			}
			return prefix + "()", []string{}
		}
		var parts []string
		var vals []string
		for _, p := range fn.Params {
			parts = append(parts, "%v")
			vals = append(vals, fmt.Sprintf("tt.args.%s", p.Name))
		}
		if nosubtestsFlag {
			if namedFlag {
				return "%q. " + prefix + "(" + strings.Join(parts, ", ") + ")", append([]string{"name"}, vals...)
			}
			return "%q. " + prefix + "(" + strings.Join(parts, ", ") + ")", append([]string{"tt.name"}, vals...)
		}
		return prefix + "(" + strings.Join(parts, ", ") + ")", vals
	}

	if nonErr == 0 && !fn.HasError {
		buf.WriteString(fmt.Sprintf("%s%s\n", innerIndent, call))
	} else if nonErr == 0 && fn.HasError {
		if iFlag || nosubtestsFlag {
			fmtStr, fmtArgs := buildFormat()
			if len(fmtArgs) > 0 {
				buf.WriteString(fmt.Sprintf("%stt.assertion(t, %s, fmt.Sprintf(\"%s\", %s))\n", innerIndent, call, fmtStr, strings.Join(fmtArgs, ", ")))
			} else {
				buf.WriteString(fmt.Sprintf("%stt.assertion(t, %s, fmt.Sprintf(\"%s\"))\n", innerIndent, call, fmtStr))
			}
		} else {
			buf.WriteString(fmt.Sprintf("%stt.assertion(t, %s)\n", innerIndent, call))
		}
	} else {
		if nonErr == 1 && !fn.HasError {
			if iFlag || nosubtestsFlag {
				fmtStr, fmtArgs := buildFormat()
				if len(fmtArgs) > 0 {
					buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.want, %s, \"%s\", %s)\n", innerIndent, call, fmtStr, strings.Join(fmtArgs, ", ")))
				} else {
					buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.want, %s, \"%s\")\n", innerIndent, call, fmtStr))
				}
			} else {
				buf.WriteString(fmt.Sprintf("%sassert.Equal(t, tt.want, %s)\n", innerIndent, call))
			}
		} else {
			var gotVars []string
			for i := 0; i < nonErr; i++ {
				if i == 0 {
					gotVars = append(gotVars, "got")
				} else {
					gotVars = append(gotVars, fmt.Sprintf("got%d", i))
				}
			}
			if fn.HasError {
				gotVars = append(gotVars, "err")
			}
			gotStr := strings.Join(gotVars, ", ")
			buf.WriteString(fmt.Sprintf("%s%s := %s\n", innerIndent, gotStr, call))
			if fn.HasError {
				if iFlag || nosubtestsFlag {
					fmtStr, fmtArgs := buildFormat()
					if len(fmtArgs) > 0 {
						buf.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\"%s\", %s))\n", innerIndent, fmtStr, strings.Join(fmtArgs, ", ")))
					} else {
						buf.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\"%s\"))\n", innerIndent, fmtStr))
					}
				} else {
					buf.WriteString(fmt.Sprintf("%stt.assertion(t, err)\n", innerIndent))
				}
			}
			for i := 0; i < nonErr; i++ {
				wantName := "want"
				if i > 0 {
					wantName = fmt.Sprintf("want%d", i)
				}
				gotName := "got"
				if i > 0 {
					gotName = fmt.Sprintf("got%d", i)
				}
				if iFlag || nosubtestsFlag {
					fmtStr, fmtArgs := buildFormat()
					if len(fmtArgs) > 0 {
						buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%s\", %s)\n", innerIndent, wantName, gotName, fmtStr, strings.Join(fmtArgs, ", ")))
					} else {
						buf.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%s\")\n", innerIndent, wantName, gotName, fmtStr))
					}
				} else {
					buf.WriteString(fmt.Sprintf("%sassert.Equal(t, tt.%s, %s)\n", innerIndent, wantName, gotName))
				}
			}
		}
	}

	if !nosubtestsFlag {
		buf.WriteString("\t\t})\n")
		buf.WriteString("\t}\n")
	} else {
		buf.WriteString("\t}\n")
	}
	buf.WriteString("}\n")
	return buf.String()
}

func formatSrc(src string) (string, error) {
	formatted, err := format.Source([]byte(src))
	if err != nil {
		fset := token.NewFileSet()
		f, err2 := parser.ParseFile(fset, "test.go", []byte(src), parser.ParseComments)
		if err2 != nil {
			return "", err2
		}
		var buf bytes.Buffer
		printer.Fprint(&buf, fset, f)
		return buf.String(), nil
	}
	return string(formatted), nil
}

func mergeFiles(existingPath, newContent string) (string, error) {
	existingBytes, err := os.ReadFile(existingPath)
	if err != nil {
		return "", err
	}
	fset := token.NewFileSet()
	ef, err := parser.ParseFile(fset, existingPath, existingBytes, 0)
	if err != nil {
		return "", fmt.Errorf("expected declaration, found unc")
	}
	fset2 := token.NewFileSet()
	nf, err := parser.ParseFile(fset2, "new.go", []byte(newContent), 0)
	if err != nil {
		return "", err
	}
	importSet := make(map[string]ImportInfo)
	for _, imp := range ef.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		alias := ""
		if imp.Name != nil {
			alias = imp.Name.Name
		}
		importSet[path] = ImportInfo{Path: path, Alias: alias}
	}
	for _, imp := range nf.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		alias := ""
		if imp.Name != nil {
			alias = imp.Name.Name
		}
		importSet[path] = ImportInfo{Path: path, Alias: alias}
	}
	var buf bytes.Buffer
	buf.WriteString(fmt.Sprintf("package %s\n\n", ef.Name.Name))
	if len(importSet) == 1 {
		for _, imp := range importSet {
			if imp.Alias != "" {
				buf.WriteString(fmt.Sprintf("import %s \"%s\"\n\n", imp.Alias, imp.Path))
			} else {
				buf.WriteString(fmt.Sprintf("import \"%s\"\n\n", imp.Path))
			}
		}
	} else if len(importSet) > 1 {
		var stds []ImportInfo
		var exts []ImportInfo
		for _, imp := range importSet {
			if strings.Contains(imp.Path, ".") {
				exts = append(exts, imp)
			} else {
				stds = append(stds, imp)
			}
		}
		sort.Slice(stds, func(i, j int) bool { return stds[i].Path < stds[j].Path })
		sort.Slice(exts, func(i, j int) bool { return exts[i].Path < exts[j].Path })
		buf.WriteString("import (\n")
		for _, imp := range stds {
			if imp.Alias != "" {
				buf.WriteString(fmt.Sprintf("\t%s \"%s\"\n", imp.Alias, imp.Path))
			} else {
				buf.WriteString(fmt.Sprintf("\t\"%s\"\n", imp.Path))
			}
		}
		if len(stds) > 0 && len(exts) > 0 {
			buf.WriteString("\n")
		}
		for _, imp := range exts {
			if imp.Alias != "" {
				buf.WriteString(fmt.Sprintf("\t%s \"%s\"\n", imp.Alias, imp.Path))
			} else {
				buf.WriteString(fmt.Sprintf("\t\"%s\"\n", imp.Path))
			}
		}
		buf.WriteString(")\n\n")
	}
	for _, decl := range ef.Decls {
		if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
			continue
		}
		var db bytes.Buffer
		printer.Fprint(&db, fset, decl)
		buf.WriteString(db.String())
		buf.WriteString("\n\n")
	}
	for _, decl := range nf.Decls {
		if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
			continue
		}
		if _, ok := decl.(*ast.FuncDecl); ok {
			var db bytes.Buffer
			printer.Fprint(&db, fset2, decl)
			buf.WriteString(db.String())
			buf.WriteString("\n\n")
		}
	}
	return buf.String(), nil
}
